(function () {
  'use strict';
  // Shared prototype access only. This is not server-side authentication.
  const accessKey = 'ordercrew-sites-demo-access-v1';
  const closeKey = 'ordercrew-sites-close-v1';
  function closeMarker() {
    try { return localStorage.getItem(closeKey) || ''; } catch (error) { return ''; }
  }
  function isOpen() {
    try {
      const entry = JSON.parse(sessionStorage.getItem(accessKey) || 'null');
      return !!entry && entry.version === 1 && entry.user === 'ordercrewdemo'
        && entry.closeMarker === closeMarker();
    } catch (error) { return false; }
  }
  function clear() {
    try { sessionStorage.removeItem(accessKey); } catch (error) {}
  }
  function signIn(username, password) {
    clear();
    if (String(username).trim().toLowerCase() !== 'ordercrewdemo' || password !== 'ordercrew2026') {
      return {ok:false, reason:'credentials'};
    }
    try {
      sessionStorage.setItem(accessKey, JSON.stringify({version:1, user:'ordercrewdemo', closeMarker:closeMarker()}));
      if (!isOpen()) throw new Error('Temporary storage unavailable');
      return {ok:true};
    } catch (error) {
      clear();
      return {ok:false, reason:'storage'};
    }
  }
  function requireDemo() {
    if (isOpen()) {
      document.documentElement.classList.remove('oc-demo-pending');
      return true;
    }
    document.documentElement.classList.add('oc-demo-pending');
    clear();
    location.replace('login.html');
    return false;
  }
  window.OrderCrewDemoAccess = Object.freeze({isOpen, signIn, clear, requireDemo});
})();

(function () {
  'use strict';
  const form = document.getElementById('demo-login-form');
  const username = document.getElementById('username');
  const password = document.getElementById('password');
  const error = document.getElementById('login-error');
  const toggle = document.getElementById('toggle-password');
  form.addEventListener('submit', function (event) {
    event.preventDefault();
    error.hidden = true;
    username.removeAttribute('aria-invalid');
    password.removeAttribute('aria-invalid');
    const result = window.OrderCrewDemoAccess.signIn(username.value, password.value);
    if (result.ok) {
      password.value = '';
      location.assign('demo.html#overzicht');
      return;
    }
    error.textContent = result.reason === 'storage'
      ? 'Je browser staat tijdelijke opslag niet toe. Sta websiteopslag toe en probeer opnieuw.'
      : 'Deze combinatie klopt niet. Controleer je gebruikersnaam en wachtwoord en probeer opnieuw.';
    error.hidden = false;
    if (result.reason === 'credentials') {
      username.setAttribute('aria-invalid', 'true');
      password.setAttribute('aria-invalid', 'true');
      password.focus();
    } else {
      error.focus();
    }
  });
  toggle.addEventListener('click', function () {
    const visible = password.type === 'password';
    password.type = visible ? 'text' : 'password';
    toggle.textContent = visible ? 'Verbergen' : 'Tonen';
    toggle.setAttribute('aria-label', visible ? 'Wachtwoord verbergen' : 'Wachtwoord tonen');
    toggle.setAttribute('aria-pressed', String(visible));
  });
  window.addEventListener('pageshow', function () { password.value = ''; });
})();

